#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Full

COMPONENT RigidBodyPhysics : 2

DEF RBC RigidBodyCollection {
  bodies [
    DEF A RigidBody {
      fixed TRUE
      position 0 5 0
      geometry DEF A_C CollidableShape {
        translation 0 5 0
        shape Shape {
          geometry Box {
            size 0.5 0.5 0.5
          }
        }
      }
    }
    DEF B RigidBody {
      position 2 4.992193 0
      linearVelocity 0 -0.4122824 0
      geometry DEF B_C CollidableShape {
        translation 2 4.992193 0
        shape Shape {
          geometry Sphere {
            radius 0.3
          }
        }
      }
    }
  ]
  joints DEF J MotorJoint {
    autoCalc TRUE
    forceOutput "ALL"
    axis1Torque 1
    axis2Torque 1
    enabledAxes 3
    motor2Axis 0 0 0
    motor3Axis 0 0 0
    body1 USE A
    body2 USE B
  }
}

